"use client";

import { useEffect, useRef, useState } from "react";

export default function SpeechPage() {
  const [supported, setSupported] = useState(true);
  const [listening, setListening] = useState(false);
  const [interim, setInterim] = useState("");
  const [finalText, setFinalText] = useState("");
  const [error, setError] = useState("");
  const recognitionRef = useRef(null);

  useEffect(() => {
    const SpeechRecognition =
      typeof window !== "undefined" &&
      (window.SpeechRecognition || window.webkitSpeechRecognition);

    if (!SpeechRecognition) {
      setSupported(false);
      return;
    }

    const rec = new SpeechRecognition();
    rec.lang = "en-US";
    rec.interimResults = true;
    rec.continuous = true;

    rec.onresult = (event) => {
      let interimText = "";
      let finalChunk = "";
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const result = event.results[i];
        if (result.isFinal) {
          finalChunk += result[0].transcript;
        } else {
          interimText += result[0].transcript;
        }
      }
      if (interimText) setInterim(interimText);
      if (finalChunk)
        setFinalText((prev) => (prev ? prev + " " : "") + finalChunk);
    };

    rec.onerror = (e) => {
      setError(e.error || "speech recognition error");
      setListening(false);
    };

    rec.onend = () => {
      setListening(false);
    };

    recognitionRef.current = rec;

    return () => {
      try {
        rec.onresult = null;
        rec.onerror = null;
        rec.onend = null;
        rec.stop();
      } catch {}
    };
  }, []);

  const start = () => {
    setError("");
    if (!recognitionRef.current) return;
    try {
      recognitionRef.current.start();
      setListening(true);
    } catch (e) {
      setError("Failed to start: " + (e?.message || String(e)));
    }
  };

  const stop = () => {
    if (!recognitionRef.current) return;
    try {
      recognitionRef.current.stop();
      setListening(false);
      setInterim("");
    } catch (e) {
      setError("Failed to stop: " + (e?.message || String(e)));
    }
  };

  const reset = () => {
    setFinalText("");
    setInterim("");
    setError("");
  };

  if (!supported) {
    return (
      <div style={{ padding: 24 }}>
        <h1>Speech to Text</h1>
        <p>Your browser does not support the Web Speech API.</p>
        <p>Try Chrome or Edge on desktop.</p>
      </div>
    );
  }

  return (
    <div style={{ padding: 24, maxWidth: 800, margin: "0 auto" }}>
      <h1>Speech to Text</h1>
      <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
        <button onClick={start} disabled={listening}>
          Start
        </button>
        <button onClick={stop} disabled={!listening}>
          Stop
        </button>
        <button onClick={reset}>Reset</button>
      </div>
      {error && (
        <div style={{ color: "#b00020", marginBottom: 12 }}>Error: {error}</div>
      )}
      <div
        style={{
          border: "1px solid #e5e7eb",
          borderRadius: 8,
          padding: 12,
          minHeight: 160,
          background: "#fafafa",
        }}
      >
        <div style={{ whiteSpace: "pre-wrap" }}>{finalText}</div>
        {interim && (
          <div style={{ opacity: 0.6, whiteSpace: "pre-wrap" }}>{interim}</div>
        )}
      </div>
      <p style={{ marginTop: 12, fontSize: 12, color: "#6b7280" }}>
        Language: en-US • Continuous: on • Interim: on
      </p>
    </div>
  );
}
